<?php
require_once __DIR__ . '/auth.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
$product=['name'=>'','brand'=>'','price'=>'','condition_type'=>'Baru','category_type'=>'Global','tier'=>'B','processor'=>'','gpu'=>'','ram_gb'=>8,'storage_gb'=>512,'storage_type'=>'SSD NVMe','display_size'=>'','weight_kg'=>'','use_cases'=>'Kuliah, Produktivitas','description'=>'','pros'=>'','cons'=>'','image_path'=>'','tokopedia_url'=>'https://www.tokopedia.com/','is_featured'=>0,'is_published'=>0];
if($id){$st=db()->prepare('SELECT * FROM laptops WHERE id=:id');$st->execute(['id'=>$id]);$found=$st->fetch();if(!$found){flash('error','Produk tidak ditemukan.');redirect('laptops.php');}$product=$found;}
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();
  foreach(['name','brand','condition_type','category_type','tier','processor','gpu','storage_type','display_size','use_cases','description','pros','cons','tokopedia_url'] as $key)$product[$key]=trim((string)($_POST[$key]??''));
  $product['price']=filter_var($_POST['price']??null,FILTER_VALIDATE_INT);$product['ram_gb']=filter_var($_POST['ram_gb']??null,FILTER_VALIDATE_INT);$product['storage_gb']=filter_var($_POST['storage_gb']??null,FILTER_VALIDATE_INT);$product['weight_kg']=trim((string)($_POST['weight_kg']??''));
  $product['is_featured']=isset($_POST['is_featured'])?1:0;$product['is_published']=isset($_POST['is_published'])?1:0;
  if($product['name']==='')$errors[]='Nama laptop wajib diisi.';
  if(!is_int($product['price'])||$product['price']<0)$errors[]='Harga harus berupa angka bulat nol atau lebih.';
  if(!in_array($product['condition_type'],['Baru','Bekas'],true))$errors[]='Pilih kondisi yang valid.';
  if(!in_array($product['category_type'],['Global','ODM'],true))$errors[]='Pilih kategori yang valid.';
  if(!in_array($product['tier'],['C','B','B+','A','A+','S','S+'],true))$errors[]='Pilih tier yang valid.';
  if(!is_int($product['ram_gb'])||$product['ram_gb']<0)$errors[]='RAM harus berupa angka.';
  if(!is_int($product['storage_gb'])||$product['storage_gb']<0)$errors[]='Storage harus berupa angka.';
  if($product['tokopedia_url']!==''&&!filter_var($product['tokopedia_url'],FILTER_VALIDATE_URL))$errors[]='URL Tokopedia tidak valid.';
  if($product['tokopedia_url']!==''&&!preg_match('~^https?://~i',$product['tokopedia_url']))$errors[]='URL harus diawali http:// atau https://.';
  $product['image_path']=trim((string)($_POST['image_path']??$product['image_path']??''));
  if(isset($_FILES['image_file'])&&($_FILES['image_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){
    $f=$_FILES['image_file']; if($f['error']!==UPLOAD_ERR_OK)$errors[]='Gagal mengunggah gambar. Periksa batas ukuran file hosting.';
    elseif($f['size']>3*1024*1024)$errors[]='Ukuran gambar maksimal 3 MB.';
    else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$exts=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($exts[$mime]))$errors[]='Format gambar harus JPG, PNG, atau WebP.';else{$folder=__DIR__.'/../uploads';if(!is_dir($folder))@mkdir($folder,0755,true);if(!is_writable($folder))$errors[]='Folder uploads tidak dapat ditulis. Periksa izin folder hosting.';else{$filename='laptop_'.bin2hex(random_bytes(9)).'.'.$exts[$mime];if(move_uploaded_file($f['tmp_name'],$folder.'/'.$filename))$product['image_path']='uploads/'.$filename;else $errors[]='Gambar gagal disimpan.';}}}
  }
  if($product['image_path']!=='' && !preg_match('~^https?://~i',$product['image_path']) && (str_contains($product['image_path'],'..') || str_starts_with($product['image_path'],'/'))) $errors[]='Lokasi gambar tidak valid.';
  if(!$errors){
    $data=['name'=>$product['name'],'brand'=>$product['brand'],'price'=>$product['price'],'condition_type'=>$product['condition_type'],'category_type'=>$product['category_type'],'tier'=>$product['tier'],'processor'=>$product['processor'],'gpu'=>$product['gpu'],'ram_gb'=>$product['ram_gb'],'storage_gb'=>$product['storage_gb'],'storage_type'=>$product['storage_type'],'display_size'=>$product['display_size'],'weight_kg'=>$product['weight_kg']!==''?$product['weight_kg']:null,'use_cases'=>$product['use_cases'],'description'=>$product['description'],'pros'=>$product['pros'],'cons'=>$product['cons'],'image_path'=>$product['image_path'],'tokopedia_url'=>$product['tokopedia_url'],'is_featured'=>$product['is_featured'],'is_published'=>$product['is_published']];
    if($id){$set=[];foreach(array_keys($data) as $k)$set[]="$k=:$k";$data['id']=$id;$st=db()->prepare('UPDATE laptops SET '.implode(',',$set).', updated_at=NOW() WHERE id=:id');$st->execute($data);flash('success','Data laptop berhasil diperbarui.');}
    else{$cols=array_keys($data);$st=db()->prepare('INSERT INTO laptops ('.implode(',',$cols).') VALUES (:'.implode(',:',$cols).')');$st->execute($data);flash('success','Laptop baru berhasil ditambahkan.');}
    redirect('laptops.php');
  }
}
$admin_title=$id?'Edit laptop':'Tambah laptop';$admin_active='laptops';require __DIR__.'/_layout-top.php';
?>
